    46  void Message::Init(void)
    47  {
    48      memset(&GetHelpData(), 0, sizeof(GetHelpData()));
    49      SetVersion(kVersion1);
    50      SetOffset(0);
    51      GetHelpData().mHeaderLength = kMinHeaderLength;
    52
    53      SetLength(GetHelpData().mHeaderLength);
    54  }
