    63  otError Message::Init(Type aType, Code aCode, const char *aUriPath)
    64  {
    65      otError error;
    66
    67      Init(aType, aCode);
    68      SuccessOrExit(error = SetToken(kDefaultTokenLength));
    69      SuccessOrExit(error = AppendUriPathOptions(aUriPath));
    70
    71  exit:
    72      return error;
    73  }
