   210  const otCoapOption *Message::GetFirstOption(void)
   211  {
   212      const otCoapOption *option = NULL;
   213
   214      memset(&GetHelpData().mOption, 0, sizeof(GetHelpData().mOption));
   215
   216      VerifyOrExit(GetLength() - GetHelpData().mHeaderOffset >= GetOptionStart());
   217
   218      GetHelpData().mNextOptionOffset = GetHelpData().mHeaderOffset + GetOptionStart();
   219
   220      if (GetHelpData().mNextOptionOffset < GetLength())
   221      {
   222          option = GetNextOption();
   223      }
   224
   225  exit:
   226      return option;
   227  }
