   311  otError Message::GetOptionValue(void *aValue) const
   312  {
   313      otError             error  = OT_ERROR_NONE;
   314      const otCoapOption &option = GetHelpData().mOption;
   315
   316      VerifyOrExit(GetHelpData().mNextOptionOffset > 0, error = OT_ERROR_NOT_FOUND);
   317
   318      VerifyOrExit(Read(GetHelpData().mNextOptionOffset - option.mLength, option.mLength, aValue) == option.mLength,
   319                   error = OT_ERROR_PARSE);
