   105  otError Tlv::Find(const Message &aMessage, uint8_t aType, uint16_t *aOffset, uint16_t *aSize, bool *aIsExtendedTlv)
   106  {
   107      otError  error        = OT_ERROR_NOT_FOUND;
   108      uint16_t offset       = aMessage.GetOffset();
   109      uint16_t remainingLen = aMessage.GetLength();
   110      Tlv      tlv;
   111      uint16_t size;
   112
   113      VerifyOrExit(offset <= remainingLen);
   114      remainingLen -= offset;
   115
   116      while (true)
   117      {
   118          VerifyOrExit(sizeof(Tlv) <= remainingLen);
   119          aMessage.Read(offset, sizeof(Tlv), &tlv);
   120
   121          if (tlv.mLength != kExtendedLength)
   122          {
   123              size = tlv.GetSize();
   124          }
   125          else
   126          {
   127              ExtendedTlv extTlv;
   128
   129              VerifyOrExit(sizeof(ExtendedTlv) <= remainingLen);
   130              aMessage.Read(offset, sizeof(ExtendedTlv), &extTlv);
   131              size = extTlv.GetSize();
   132          }
   133
   134          VerifyOrExit(size <= remainingLen);
   135
   136          if (tlv.GetType() == aType)
   137          {
   138              if (aOffset != NULL)
   139              {
   140                  *aOffset = offset;
   141              }
   142
   143              if (aSize != NULL)
   144              {
   145                  *aSize = size;
